    govLiveDesc: 'التصميم أعلاه هو الغرض من الحوكمة ؛ صفحة الحوكمة هي المكان الذي تحدث فيه. يتم سرد المقترحات تحت المقترحات، التي تم تمريرها ورفضها، مع كل من مؤلفها ونصها ومكان التصويت. يكلف فتح العرض رسومًا قدرها 10000 رمز DeHub، يتم تأكيدها على السلسلة، ولكل اقتراح صفحته الخاصة مع مناقشة مترابطة. التصويت مجاني: يتم ترجيح صوتك بشارتك، ويستمر التصويت لمدة سبعة أيام، ويمر الاقتراح بأغلبية مرجحة مع تصويت عشر محافظ مختلفة على الأقل، لذلك لا يمكن لأي حامل واحد تمرير شيء لم يره أحد.',
