    importantNotice: 'إشعار مهم',
    incentiveFlywheel: 'دولاب الحوافز',
    intro1: 'DeHub بديل مفتوح المصدر ومقاوم للرقابة لمنصات الوسائط التقليدية، يخدم صناعات إنشاء المحتوى والبث والألعاب. نظام بيئي يستطيع فيه أي شخص تحقيق الدخل من أول مشاهدة، دون خوف من الطرد من المنصة أو الحظر الخفي أو الإسكات أو التلاعب به ليكون أي شيء سوى ذاته الحقيقية. للتحدث والتفكير بحرية، بعيداً عن عقلية القطيع، والتعبير كما يشاء.',
    intro3: 'بصفتنا أول بروتوكول يرمّز المحتوى عام 2023، بنينا حلاً مستداماً للتمويل الاجتماعي يمكّن المبدعين والمستهلكين بعدد وافر من الأدوات. تشمل الميزات الاتصالات الخاصة المشفّرة، وإصدارات الدفع مقابل المشاهدة على السلسلة، والاشتراكات القابلة للتداول، والرسائل المباشرة المدفوعة، والمحتوى القابل لفك القفل، وعائدات الإعلانات المشتركة وغيرها كثير مما تغطيه هذه الوثائق بالكامل.',
    intro4: 'بما أن البيانات هي النفط الجديد، قد يكون من الحكمة بناء قاعدة مجتمعك الأساسية هنا واستخدام تطبيقات التواصل الاجتماعي الحالية لتوجيه المستخدمين إليها، لتنمية قاعدة بياناتك القيّمة وضمان بقائك مقاوماً للرقابة. مهما حدث، لا تفقد التواصل مع جمهورك أو معجبيك أو مجتمعك أو عملائك.',
