    liveStreamDesc: 'انتقل إلى البث المباشر من مؤلف المنشور أو في متصفحك أو من برنامج ترميز. يتم نشر التدفقات إلى DeHub الخاصة وتشغيلها عبر WebRTC في الوقت الفعلي تقريبًا، مع Livepeer كاحتياطي تلقائي عندما لا تتمكن الشبكة من الوصول إلى الإدخال. كل بث غير مصرح به ومقاوم للرقابة، وله دردشة خاصة به، ويتحول إلى إعادة في اللحظة التي ينتهي فيها.',
    marketsB1: 'أسماء المستخدمين:',
    marketsB1Desc: 'في dehub.io/usernames، تصفح المقابض المعروضة للبيع بأسعار ثابتة بالدولار، وابحث عن المقابض التي تريدها، واشترِها. تنتقل الأسماء التي تشتريها إلى خزنتك، بحيث يمكن لحساب واحد امتلاك العديد منها وارتداء ما يحلو له ؛ قم ببيعها أو تحريرها من الخزنة أو الإعدادات. يمكن أيضًا المطالبة بأسماء مكونة من حرف واحد أو حرفين. إذا كان الاسم غير مطالب به ببساطة، فإن الصفحة تقول ذلك بدلاً من بيعه لك.',
    marketsB2Desc: 'في dehub.io/accounts، الحسابات بأكملها معروضة للبيع — المقبض، المنشورات، المتابعين، سجل الإكراميات واستحقاقات الشارة. يحتفظ البائع بمحفظته وكل شيء فيها، ولا يأخذ DeHub أي قطع، ولا يتم التحويل إلا بمجرد قراءة الدفعة مرة أخرى خارج السلسلة.',
