    stagesB3Desc: 'درج نص مباشر يكتب ما يُقال في الغرفة لحظياً، وتحويل النص إلى كلام يتيح لك المشاركة دون ميكروفون.',
    stagesB5: 'الجدولة والتذكير:',
    stagesB5Desc: 'أعلن عن مسرح مسبقاً برابط دعوة قصير وبطاقة مشاركة خاصة به. ويُنبَّه كل من ضبط تذكيراً قبيل البدء، ومرة أخرى لحظة انطلاقه.',
    stagesB6: 'الترجمة النصية والترجمة:',
    stagesB6Desc: 'ترجمة نصية مباشرة لكل متحدث، مترجمة إلى اللغة التي يقرأ بها كل مستمع. ويُحفظ النص الدائم على حدة بعد انتهاء الغرفة.',
    stagesB7: 'الدبلجة المباشرة:',
    stagesB8: 'دردشة الجمهور ومشاركة الشاشة:',
    stagesDesc2: 'ما يميز مسارح DeHub هو طبقة الإنتاج. فيحصل المضيفون على لوحة صوت بأسلوب منسّقي الأغاني تمزج المؤثرات الصوتية ومقاطعهم الموسيقية ومحطات الراديو المباشرة في صوت الغرفة المنشور، إضافة إلى مؤثرات الصوت، فيبدو المسرح كبرنامج منتَج لا كمكالمة جماعية. ويستطيع المضيفون مشاركة شاشتهم وإدارة كل شيء من المتصفح دون OBS أو مفاتيح بث، وجدولة غرفة مسبقاً ليكون الجمهور بانتظارهم قبل فتح الأبواب.',
    stagesDesc3: 'الغرفة قابلة للقراءة أيضًا. تعلق الترجمة المباشرة على كل متحدث أثناء حديثه ويتم ترجمتها إلى أي لغة يقرأها كل مستمع، لذلك يمكن اتباع مرحلة بلغة لا يتحدث بها أحد على خشبة المسرح. تمضي الدبلجة المباشرة خطوة أخرى إلى الأمام وتنطق الغرفة بصوت عالٍ بصوت المضيف المستنسخ، والذي تتم فوترته كل دقيقة بعملات DeHub الرمزية. يحافظ درج النصوص المباشر وتحويل النص إلى كلام على إمكانية استخدام الغرف بدون ميكروفون، ويتيح لك مشغل الركن الصغير المستمر الاستمرار في تصفح بقية التطبيق أثناء تشغيل المسرح.',
    stagesTitle: 'المسارح: غرف صوتية مباشرة',
