    intro2: 'البرنامج بيكبر من خلال شبكة مناجم ديسنترياليزيت، بتوفر قوة حوسبة مشتركة لتهOST، ترميز، و توزيع المحتوى، و حسب التصميم بيبقى موجود دايما.',
    accountsTitle: 'حِسابات & تِسجيل الدَّخول',
    accountsDesc2: 'شخص واحد بيستطيع يجرى عدة هوويات من نفس المتصفح. هده الهويات بتدبر من خلال الإعدادات → ملف الشخصي: أضف حساب، تبدل بينهم، وDeHub بتغير جلسة كامله — محفظة، تغريدات، رسائل وإشعارات — في خطوة واحده. إضافه ملف شخصي ما بيخليك تخرج من الملف الشخصي اللي انت فيه، وتبديل ما بيستطيع يكمل بيرجع لك المكان اللي كنت فيه. عدد الملفات الشخصية اللي بتستطيع تخزينها في القائمة بتتوسع مع رتبة استيكينجك.',
    accountsB2: 'بريد الكتروني أو رسالة نصية؟',
    accountsB4: 'مُتَعَدِّدَةِ المُوْفَقَاتِ',
    accountsB4Desc: 'حافظ على حسابات كتير جنب جنب في الإعدادات → الملف الشخصي، وتبدل بينهم بدون تسجيل خروج وورود تاني. مستوى رتبةك بتحدد كم عدد الحسابات اللي بتستطيع تحميلها.',
    accountsB5: 'جديدو:',
    uploadDesc: 'في لوحة التحكم بتحميل مستخدمين فوق، رَحَشِ كيف بسّطه ما شغّلها أي شخص ليُحمّل محتوى بسرعة، وبضغّة نقرات فقط يُنشيط ما يلي:',
