    uploadEarn: 'دِهوب توكِيز بِطَلَبِ تِيباتِ منِ الدَّاعِمينِ وِتَعَلَّوْ فيِ الرَّانِكينغِ لِيَكْتِسِبواِ أَكْثَرِ حَصَّةٍ منِ الرِّبْحِ المُنْجَزِ عَنِ الإِعلَاناتِ',
    labelGallery: 'غاليريات:',
    labelAudio: 'صوتية:',
    allowanceIntro: 'بِسْتْفَاضَةٍ، ماَشْتَرِكْشْ في دِهْيُوبْ كُلّ يَوْمٍ حَتَّى تَبْلُغْ حَدٌّ يَتْعَدّى بِهَا حَسَبَ رِيْزْقِكَ (بَادْجِ سْتَاكْيْنْغْ). كُلّ وَاحِدٍ يَبْدَأْ بِعَشْرَةِ مَوْضُوعَاتْ نَصٍّ وَجِيجَا بايْتْ (جِيجَا بايْتْ لِلْفُوتْوْ، الصُّوَرْ، الصَّوْتْ) كُلّ يَوْمٍ. لوَ عَصَيْتَ حَدٌّ مِنْ هَذَا، البَاقِي مِنْ هَذَا اليَوْمِ يُدْفَعْ بِدِهْيُوبْ تُوكِنْزْ: 10 سَنْتْ لِلْمَوْضُوعَاتْ نَصٍّ، $2 لِلْجِيجَا بايْتْ، وَهِيَ تُدْفَعْ فَقَطْ عَلَى الْبَقِيَّةِ الَّتِي تَعْتَدَى عَنِ الحَدّ.',
    allowanceIntro2: 'الرسائل النصية والميديا في برولز مختلفين. لو تنفد واحد منهم ما يلمس الآخر، يعني لو استهلكت يومك في رفع فيديو، مايعنيش أن النصيات العشرة بتتأثر. كل واحد منهم بيستريح عند منتصف الليل بتوقيت يو تي سي.',
    allowanceHowDesc: 'الترتيب مهم و هو متعمد: ما بتدفعش على أي ما نشرش، و ما بتحمليش ملف كبير ليقولو بعد كده إنك ما بتستطيعش تدفع عليه.',
    allowanceStep1Title: 'قبل الرفع',
    allowanceStep1: 'البرنامج يقارن السعر مع ما قمت بتدويره اليوم ويثبت إن محفظتك بتغطيه. مش بتتسحبش شي ولا بتترفعش شي حتى ما ياخد موافقة.',
    allowanceStep2: 'مُشْتَرَكََتِكُ تَتَعَلَّقُ بِالْحِسَابِ الْمُجَّانِ، وَلاَ تَتَعَطَّلُ النُشْرَةُ حَتَّى تُدَفَعَ الدَّفْعَةُ.',
    allowanceStep3: 'واحدة نقل، واحدة توقيع، لروابط ما بعد ده، بس. بتتقرر حسب أي من Base أو BNB Chain بتحوي كفايه من توكنات DeHub.',
    allowanceUnpaidDesc: 'البوست مايزال مشتغل. المبلغ الغير مدفوع مايزال مفتوح ضد حسابك ويوقف البوست التالي المدفوع حتى يتم تسويته — لكن مش البوستات المجانية. كل ما ييجي من راتب غداً هو لك دائماً، سواء كان هناك أي شيء مش تسويته أو لا.',
    allowanceCounts1: 'نصّ مَفتوح (بِغَير صور أو فيديوهات) يُستهلك واحد من قِطَع نصّك اليوميّة.',
    allowanceCounts2: 'فيديو، صور، ومقاطع صوتية بتستهلك حجم الملف من حصة البيانات — بما فيها الثومبنايل، لأنهم محفوظين ومقدمين كمان.',
    allowanceCounts3: 'الكووتات بتحسب كمان زي البوست ده، كووت مرفق فيديو بيستهلك بيانات.',
    allowanceCounts4: 'الحد الفائض بيكون على أساس النسبة المئوية، مايشوفش يرفعش للجيلابايت كامله. لو مايكبر 200 ميغابايت من تحميلك عن الحد المسموح، بتدفع عن 200 ميغابايت فقط.',
    allowanceCounts5: 'إعادة نشر، تعليقات، ردود، نصائح، ورسائل كلها مجانية ولا تاخدش من الميزانية.',
    autoFrac1: 'كل ما يروّج أو يروّج له من تصعيد أو بثّ، ممكن يصنع له NFT بتقنية ERC-1155.',
