    fracStep1Desc: 'اختر لتحويلها إلى NFT من نوع ERC-1155 مقسم إلى 1,000 جزء قابل للتجارة، وتظهر المنشورة على أي حال. إذا تركتها، ستتمكن من تحويلها لاحقًا.',
    fracStep2Title: '2. قرار المبدع',
    fracStep2Desc: 'المصممين بيختاروا كم من 1,000 جزء من عملهم بيبيعوها أو بيحتفظوا بيها أو بيوزعوها على مجتمعهم.',
    fracStep3Desc: 'المُؤيدين يشترون حصصًا، ويصبحون شركاء يُحصلون على عوائد متناسبة من كل مصادر الدخل.',
    forFans: 'للمُحِبّين',
    forFansDesc: 'مُفَاضِلَة مَاليَّة مُتَعَدِّدَة من خِلَال دعم نجوم جَدِيدَة، واسْتِثْمَار مُتَدَاوَل، وشارِكَة مُبَاشَرَة في نَجَاح المُخْتَرِعِين.',
    comparisonDesc: 'شوفش كمان منصة سوشيالفي الأخرى ماينها الكرييتورز لازم يوصلوا قيمة دائمة لتوكناتهم أو شيرزهم أو كيزهم ليحافظوا على قيمتهم، ديهوب المحتوى بيولد دخل مستمر لحياة الكرييتور. بعد ما يخلقه المحتوى بيكسب دخل من الإعلانات دائمة - بيوفر دخل سلبي، بلا ترخيص، ضد التصفية، لخلود، ماعندكش لازم الكرييتور يوصل جهد دائمة.',
    thPlatform: 'براتفورم',
    dehubModel: 'اختياري ERC-1155 لاصق (mint)، مقسم إلى 1,000 قطعة لكل تحميل',
