    tipDesc2: 'تُسجل النصائح التي يتلقاها المبدعون والنصائح التي يقدمها المشاهدون في لوحات صدارة منفصلة مع عدد المشاهدات والمشتركين التي تحدد الحصص في عائدات الإعلانات. يتلقى أصحاب مصلحة رموز DeHub حصصهم النسبية من إجمالي أرباح البروتوكول.',
