    feedsHomeDesc: 'مِزَج من نَصّ، صُورَة، مَقَالَة، فيديو، صوت، وبِوستات حَيّة. يُمكِن الإِعْجَاب، التَكْلِيف، التَرْجِيع، الإِشْهَاد، الإِحْفَاظ، والتِهْديَة بالتوْقِيع في كُلّ كَرْتَة، وبِسَبَب ذَلِكَ يُمكِن حِفْظ البِوستات أو تَحْفِيزها على وَجْه الدَّفْع أو تَحْفِيزها على "وَتْش2إِيرْن". لِكَيْ لا يُمكِن أَحَد أن يُفْلِيدَها، تُحْمِل الإِتِيرَات الوِيلَاي عددًا مُقَيّدًا من بِوستات كُلّ مُؤلِّف في اليَوْم: بِوست واحد بِغَير رِقَابَة، وواحد أَكثَر لكلّ رِقَابَة، حَتَّى أَرْبَعَ عَشَرَة في رِقَابَة مِيجَلُودون. كُلّ شَيْء يُظْهِر على نِظَام المُؤلِّف وَ في تَرْتِيب "الِتَّبِيع".',
    feedsShortsDesc: 'مِقْطَع فيديُو مُسْتَقِيم، يُمكِن التَصْفِيف فيه، كَمَا في تِيكْتوك. الإِشَارَات المُقْفَلَة على التَصْفِيف تُحْتَوِي بين المِقْطَعَات، وَ التَّسْعِير يُمكِن أن يُتَوَجَّه لكلّ مِقْطَع.',
    feedsReactionsDesc: 'عَشَرَة تَعَاتِير تَحْتَ كُنْزَة الإِعْجَاب: إِعْجَاب، حِبّ، تَعْتِيم، حَرّ، مِئَة، لُول، حَزِين، بَكِي، مِعَاء، وَ كَرْهَة. كُلّ وَاحِدَة من هَذِهِ التَعَاتِير، إِلاَّ كَرْهَة، تُحْسَب في عَدَد الإِعْجَابات للِبِوست. ضَغْط مِثْلَان على البِوست لِيِعْجَب بِهِ، وَ ضَغْط ثَلاثَ مَرَّات لِيُحِبَّهُ، وَ إِحْتِكاك الكُنْزَة لِيُظْهِر مَن تَعَاتَر وَ بِمِثْلَ مِثْلَ. الرَّمْز المُقَدِيم على الكَرْتَة هُوَ التَّعَاتِير الأَكْثَر لِلِبِوست. التَّعَاتِير مُسْتَقِيمَة بِرِقَابَة التَّعَاتِر، فَمَن تَعَاتَر يُمكِن أن يُؤثِّر كَمَا عَدَدُهُ.',
    articlesDesc: 'الكِتْبَة الطَّوِيلَة لَدَيْها مِودَة مُخْتَلِفَة. اِسْتَعْمِل المُؤلِّف المُكْتِب من "بِوست" إلى "مُقَالَة" لِيُحْصِل على رَأْس مُقَالَة، جِسْم بِيْنَ 20,000 حَرْف، مِصْبَاح تَصْفِيف، صُورَة غِطَاء، وَ مُحَاكَاة كَيْفَ سَتَنْظُر. تُنْشَر المُقَالَة كَمَا بِوست أَيَّام، فَيُمكِن التِهْديَة، الإِشْهَاد، حِفْظها، وَ التَّشْريِك، وَ تُحْصِل على كَرْتَة مُشَارَكَة مُخْتَلِفَة حِينَ يُنْشَر الرِّبْط في مَكَان أُخْرَى.',
    articlesB1Desc: 'رُؤُوس، تَعْتِيم، قَائِمَات، وَ رِبَاطات من مِصْبَاح التَّصْفِيف، بِمُحَاكَاة قَبْلَ النُشْر.',
    multipostDesc: 'نُشْر على دِيهُوب وَ على حِسَابَاتك الإِجْتِمَاعِيَّة الأُخْرَى في وَاحِدَة وَاحِدَة. اِصْلِح الحِسَابَات وَاحِدَة في الإِستِتِيرَات → مُشْتَرِك، ثُمَّ اِخْتَر مَكَان كُلّ بِوست من الرَّمْز المُشْتَرِك في المُكْتِب. دِيهُوب تَبْقَى مَكَان البِوست؛ النُّسْخ تُحْمِلُهُ إلى الأَجْسَام الَّتِي تَمْلِكُها في مَكَان أُخْرَى.',
