    notificationsTitle: 'الإشعارات',
    notificationsDesc: 'كل ما يحدث لك يصل إلى مركز إشعارات واحد، مقسم إلى علامات تبويب بحيث لا تدفن الدفعات التعليقات. التعليقات والإجابات، التفاعلات على بوستاتك، المتابعين الجدد، التبرعات والشراء، تذكيرات المرحلة، والوهلة التي تذهب فيها المرحلة التي حجزتها حية، نشاط المجتمع، وإشعار عندما يتم إطلاق ميزة طلبتها على لوحة الطلبات بالفعل — كل ذلك في مكان واحد، معThumbnail لما يتعلق بالإشعار حتى تتمكن من تمييزها بسرعة.',
    notificationsB1Desc: 'إفضليات حسب الفئة في الإعدادات تحدد ما يتم إرسالها على الإطلاق، لذا يمكنك تجاهل التبرعات والتفاعلات. علامات التبويب مرتبة حسب النشاط، كل منها يظهر عدد غير قرأتها الخاص بها، ويمكنك الاشتراك في إشعارات الدردشة العامة مع حد على عدد ما يصل إليه في الساعة.',
