    allowanceBadgeNote: 'الشارة تحرك النصين سوا — سماحية مجانية أكبر وسعر أرخص لأي شي بعده. الخصم هو نفس السلم اللي يحصلوا عليه أصحاب الشارات لما يشتروا توكنز DeHub، من 5% لـ "كراب" إلى 30% لـ "ميجالودون"، يعني في جواب واحد لكم تسوى الشارة. السماحية حقك تجي من الشارة اللي كسبتها: المستوى اللي يلفه لك داعم يظهر ببروفايلك، بس ما يعطيك سماحية النشر حقه.',
