    tokenisedDesc: 'أي تحميل أو بث مباشر على DeHub تقدر تحوله لـ NFT بنظام ERC-1155 متجزئ لـ 1000 قطعة بالضبط. التوثيق اختياري: المنشور ينشر خارج البلوكشين أول ما ترسله — بدون محفظة، بدون توقيع، بدون غاز — وتقدر توثقه أي وقت تشتيه من المنشور نفسه. بمجرد ما توثقه، المبدع يكون عنده تحكم كامل كم يبيع من الأجزاء وكم يخلي لنفسه، وهذا يخلق نموذج ربح جديد يقدروا المعجبين يستثمروا فيه بالمحتوى اللي يثقوا بنجاحه - يعني "يراهنوا" على مستقبل نجوم محتملين من خلال شكل ثوري من توكنز المعجبين.',
