    superPowersMore2: 'جميع القوى اثني عشر قوة تعمل الآن و مدرجة في التطبيق. Comment Anchor يحتفظ بتعليقك في أعلى حوار شخص آخر. Signal Flare يرسل إشعارًا واحدًا إلى كل حساب يتابعك. Flak Jacket يجعل المنشور منيعًا من القبور الانتقادية أثناء تشغيله. Team up يسمح بجمع ما يصل إلى ثمانية حسابات من أجل قوة الميزانية، بحيث يرتدي كل عضو شارة توفرها الميزانية المشتركة. Front Row يضع المسرح الذي تستضيفه في أعلى سلاسل المسرح. Deep Current يمنح أحد منافذك إلى منشور شخص آخر.',
    superPowersMoreV2: 'جميع القوى اثني عشر قوة تعمل الآن و مدرجة في التطبيق. Comment Anchor يحتفظ بتعليقك في أعلى حوار شخص آخر. Signal Flare يرسل إشعارًا واحدًا إلى كل حساب يتابعك. Flak Jacket يجعل المنشور منيعًا من القبور الانتقادية أثناء تشغيله. Team up يسمح بجمع ما يصل إلى ثمانية حسابات من أجل قوة الميزانية، بحيث يرتدي كل عضو شارة توفرها الميزانية المشتركة. Front Row يضع المسرح الذي تستضيفه في أعلى سلاسل المسرح. Deep Current يمنح أحد منافذك إلى منشور شخص آخر.',
