    feedsHome: 'الروابط الرئيسية:',
    feedsPollsDesc: 'سوي منشورات استطلاع رأي وجمع الأصوات مباشرة داخل الصفحة. النتائج تتحدث لايف طول ما الاستطلاع مفتوح، وأول ما يخلص الوقت، كل واحد يشوف النتيجة النهائية: الأشرطة، والنسب المئوية، والمجموع، مع علامة صح على الخيار الفائز واختفاء أزرار التصويت.',
    feedsDubDesc: 'سمع فيديو بل لغةك: اختر دوب من قائمة الأوضاع أو خيارات الفيديو ويتعرف الكلام المترجم على الفيديو مع صوت الأصلي المخفض تحتها. الدوبنج خيار اختياري، وضغط زر الكلام يعطي الدوب والصوت الأصلي حجميهما.',
    feedsMedia: 'فيديوهات وصور في الشبكة',
    feedsMediaDesc: 'يظل فيديوهات وصور في وضعها الأصلي بدلاً من أن تكون في حزم سوداء. على الهواتف، يأخذون نصف الشاشة تقريبًا ويلعبون كإشعارات مكتومة مع زر غير صامت فقط؛ انقر على واحد وسيفتح في متصفح Shorts وسيستمر في تشغيل آخر فيديوهات Shorts. على الأجهزة المنزلية، يأخذون ثلاثة أرباع الشاشة، مع ظهور إضافات على الماوس. يتبع-carousel Shorts أول مشاركة على الصفحة الرئيسية ويأتي مرة أخرى في الأسفل، ولا يظهر نفس المبدعين مرتين متتاليتين.',
    feedsSoundtrack: 'أغاني الصور:',
    feedsSoundtrackDesc: 'تظهر الصورة ككبسولة زجاجية صغيرة تفتح في موجة في أسفل الصورة، وتلعب مباشرة من feed، ويمكنك تحريكها للبحث. الصور التي تحتوي على أغنية تفتح في Shorts؛ الصور العادية تفتح في المنشور.',
    feedsShare: 'النشر الغني',
    feedsShareDesc: 'تُفتح روابط Polymarket و Manifold و Snapshot و Audius و صفحات DeFi و غيرها في بطاقات غنية مع شعار المصدر الخاص بها. يُنشئ مشاركة من DeHub صورة لها، بما في ذلك المنشورات النصية، داخل إطار DeHub مع تفاعلها.',
    communitiesB4: 'تطوير وتنظيم',
    communitiesB4Desc: 'ادعُ متابعينك للمجتمع وشوف من اللي استلم الدعوة، وضِف المنشورات اللي قد نشرتها من قبل بدون ما تنقل التفاعل حقها، وشوف الأعضاء اللي شاركوا مؤخراً وهم متكرمين.',
    aiSuiteB6: 'المهام المرسلة من قبل الوكيل',
    aiSuiteB6Desc: 'تخديمك رسالة خاصة، وتشغيلها على العديد من الحسابات في نفس الوقت، وتخطيطها، أو تحديد المهام اليومية مثل نشر المحتوى والتفاعل المحدود. يمكن للوكلاء العمل معًا في مجموعات مهام، ويتم نشر المحتوى المجدول بحيث يبقى ضمن الحد الأقصى للنشر، وتبدأ عدد الوكلاء الذي يمكن تشغيله بناءً على شارةك.',
    featureBoardDesc: 'DeHub مبني بمشاركة مجتمعه. اطرحوا أفكاركم في لوحة طلبات الميزات، وصوتوا على طلبات غيركم، وشوفوها وهي تنتقل لقسم "تم الشحن" (Shipped) — ولو الميزة اللي طلبتوها نزلت، التطبيق بيبلغكم بإشعار خاص. الطلبات الحين تفتح كـ "مساحة عمل" تعتمد على كتابة الفكرة أولاً: اشرح فكرتك، أو تحسين، أو بلاغ عن مشكلة، وارفق صور، وانشرها بخطوة واحدة.',
    featureBoardDesc2: 'الملاحظات لها صفحة خاصة تجمع كل ما نشرته المجتمع، يمكن الوصول إليها من القائمة الرئيسية والقائمة الأدوات.',
