    povrDesc1: 'حلولنا في مجال الإعلانات بتختلف عن كل ما شافناه قبل كده في الأسواق القديمة أو الأسواق اللي بتستخدم البلوك تشين، و بتخدم غرض فريد داخل تطبيقنا.',
    povrDesc2: '"Proof of View" هيا واحد بعد و ما بتتعرّفش، ما بتضيفش فائدة كبيرة للستخدمين ولا للملّاكين.',
    povrDesc3: 'ياَلاَ لوَ كانَتِكَ تِسْتَطِيعُ تَبْيِينِ أَنَّ المُشَاهِدِينَ حَقِيقِيِّينَ بِغَيْرِ إِسْتِهْلَاكِ مُحَوِّلِاتِ البِلاَك أوِ الغَازِ؟ ياَلاَ لوَ كانَتِكَ تِسْتَطِيعُ إِسْتِغْلَالِ كُلِّ مِحْفَظَةٍ مَالِيَّةٍ لِلْوَالِيتِ، مَآ أَسْفَلَ تَقْلِصِ التَّبَايُدِ، بَلْ لِيُكْثِرَ رِجْعَةَ العَوَانِ لِلْحَمَلَاتِكَ؟ مَآ أَسْفَلَ تَقْلِصِ النَّفَقَةِ، بَلْ كُنْ أَكْثَرَ رِجْعَةَ!',
    povrDesc4: 'برنامجنا، مع براءات الاختراع المتوقعة، بيستعمل نظام تصنيف غير مسبوق ب13 طبقة، مدمج مع شهادات التحقق الخاصة بنا، اللي تم التركيز عليها في هذا المقال السابق عن الميزة.',
    povrDesc5: 'بيدروهمو "دليل على النظر والتسلسل" أو "دليل على النظر والتسلسل" (POVR).',
    problemAmount: '$84 مليار سنويا لحد ما يربو على $125 مليار سنويا',
    problemDesc2: ', متوقع زيادته ل$170 مليار سنة 2028. مستغلين يستخدمون بوتات معقدة ووسائل متقدمة لسرقة إنفاق الإعلانات، بتؤثر على المؤشرات وربح الاستثمار، مع أن ما بين 20-30% من إنفاق الرقمي بيضيع على حركة مرور مزيفة.',
