    sophisticatedBots: 'بوتات متطورة:',
    sophisticatedBotsDesc: 'بوتات متقدمة بتتخد كمان سلوك البشر، بتخليهم يخلوا كLICKS زيف، مشاهدات فيديوهات زيف، ومملوءات أشكال زيف.',
    incentivesDesc: 'المنصات التكنولوجية الإعلانية كانت تاريخيًا تعطي الأولوية للكمية، لا للإنسان الحقيقي، مما خلق فرصًا للاحتيال.',
    followMoneyDesc: 'الإنفاق على الإعلانات الرقمية زيادته، زيادته كمان حافز للسرقة و الغش ليه يسرقوا الأموال.',
