    skewedDataDesc: 'يَشُوِّلُ الإِحصَائِيَّات، مُسَبِّبًا لِلْقَرَارَاتِ العَمَلِيَّةِ الرَّدِيئَةِ',
    lostRoi: 'فقدت العائدات (ROI)',
    lostRoiDesc: 'يَحْبِطُ عَنِ الْمَشْهُورَاتِ مِنْ نَجَاحِهَا، وَلَوْ كَانَتِ الْحَمَاسَاتِ عَظِيمَةً.',
    howItWorksDesc1: 'المايزك ما تيجي في يدك، مايزك الرتبة ما تفتحلك، مايزك ما تيجي من الإعلانات، ومايزك ما ييجي الشركات بتدفعوا ليك من أجل الإعلانات.',
    howItWorksDesc2: 'هَذِهِ الطَرِيقَةُ تَفِيدُ كُلَّ الإِكُوْسِسْطِيمَ وَلاَ تَفِيدُ حَاتِيَّةً وَاحِدَةً مَخْلُوصَةً. مُخْتَرِعِي الْمُحْتَوِيَاتِ، مُسْتَهْلِكِيْنَ، مُحْتَوِلِيْنَ، وَشَرِكَاتٍ تَتْبَعُ الْإِعْلَانَ عَلَى الْمُصْطَلَحِ كُلُّهُمْ يَنْتَفِعُونَ بِأَكْثَرِ أَجْرٍ.',
    howItWorksDesc3: 'البيانات المالية هيا الأكثر ربحية، وبياناتنا بتتجمع بشكل فريد في نظام واحد يمكن للمعلنين الاستفادة منه لهدف الجمهور. ده مش ممكن يكونش كده خارج الشبكة، لأن بيانات الحسابات المصرفية بتكون خاصة بينما البلوكشين علانية.',
    howItWorksDesc4: 'بِكُلّ ما يُمكِنُكِ التّوجُّه لِلْحُوتَاتِ (الْمُشْتَرِيَاتِ الْكَبِيرَاتِ) وَالْعُظَمَاءِ (الْمُشْتَرِيَاتِ الْغَنِيَّاتِ) وَإِعْطَاءِ عَرَائِصَ خَاصَّةٍ أَوْ خُصُومَاتٍ لِلْصِغَارِ (الْمُشْتَرِيَاتِ الصَّغِيرَاتِ) فِيمَا فِيهِ، هَذَا سَيُغَيِّرُ كَيْفِيَّةَ الْإِعْلَانِ فِي كُلِّ الْعَالَمِ. مَاذَا يَعْنِي ذَلِكَ لَا يُرِيدُهُ أَحَدٌ؟',
    preventFraud: 'كيف دا يمنع الغش؟',
    preventFraudDesc1: 'بوتين بتقل ربحيتها لما كل نشاطه بيظهر على السلك (on-chain) بسهولة، مايبقىش كده مشكله لربط الفاعلين السيئين (bad actors) و في النهاية بتتجمع قاعدة المستخدمين كمان. الإعلانات بتتوجه لصفوف أعلى، مايبقىش قيمة ممكن استخراجها من الأسفل، حيث مايبقىش كده إلا غش بقى. فوق كل ده، نظامنا التوزيعي للمoderation بيسمح بتحديد و منع نشاطات غير قانونية بشكل أكثر كفاءة.',
