      'رَفْعُ $1,000,000 لِلْفُورْكُ الْفَاضِحَةِ BJ (الآن fan.site) مِنْ قِبَلِ الْمُشَارِكِينَ فِي الْمُقَارِضَةِ، مُقَارِضَاتِ التَّشْغِيلِ وَالْبَيْعِ الْعَامِّ',
