    businessesText: 'إِذا كُنتَ بتستخدم الخِدمَة على اسم شركَة أو مُؤسَّسة، بتُؤكّد ليَ أنَّكَ بتَستَحِقُّ أن تَعملَ باسمها، وأنَّها بتَقَبَّل هذِهِ المُعاهَدة.',
    walletText1: 'بِكُلّ سَهْلَةٍ تُستَخْدَمُ جُزْءًا مِّنَ الخِدمَةِ كَالِتَّجْوَلِ وَالِاكْتِشَافِ لِلْمَوْضُوعَاتِ بِغَيْرِ وَصْلِ مَحْفَظَةٍ (وَلِيت). وَلكِنَّكَ حَاجَةٌ لِمَحْفَظَةٍ مُتَوَافِقَةٍ مَعَ الكُرُوبْتِو لِيَسْتَخْدِمَ مِثَالًا مِيزَانِيَّةً وَشَرِكَةً فِي التَّشْرِيكِ.',
    walletItem2: 'كل المعاملات اللي بتتم من خلال محفظةك',
    tokenUsageItem2: 'اشتراك في المبدعين',
    purchaseLimitsText: 'الحد الأقصى للشراء اليومي عبر بطاقة البنك هو 500 دولار أمريكي (مستوى الدولار). هذا الحد موجود من أجل الأمن والتوافق مع القوانين.',
    refundsPolicyText: 'بسبب طبيعة المعاملات في البلوكشين اللي غير ممكن تراجعها، الرفود ممكن يتطبق فقط لو البيع مش كالموصف أو مش بيعمل ما بيحتمله من أي شكل. كل شراءات التوكينات نهائية ولا ممكن تراجعها أو إلغاء أو رفود إلا لو الشروط دي مش بتطبق.',
    feesAndGasText: 'كل شراء توكنه بيشمل رسوم إضافية 1% عشان تكاليف الغاز والخدمات. ممكن هده الرسوم تتغير حسب ظروف الشبكة ومزودي الخدمات الخارجية.',
    fiatOnRampText: 'نحن ممكن نوفر وصول لخدمات "on-ramp" لالعملات الورقية من طرف ثالث لتيسير شراء الرموز. هذه الخدمات بتقدمها طرف ثالث مستقل و بتخضع لشروطها الخاصة. ما نكون مسؤولين عن:',
    fiatOnRampItem2: 'ديلاي أو فشل في المعاملات الدفعية',
