    fiatOnRampItem4: 'تأكد من اتباع قوانين الدفع المحليه فى منطقةك.',
    fiatOnRampNote: 'تتفق على الالتزام بكل القوانين والقوانين المعمول بها بشأن شراء الأصول الرقمية في منطقتك.',
    burnMintText: 'DeHub بحقها بتستخدم الوظيفة "burn & mint" اللى بتعمل كدفاع عن مستخدمينا من هجمات، هكس، استغلال، أخطاء مستخدمين، أو إفلاس بورصات. ده آلية أمان بتعمل لحماية المجتمع وتضمن استقرار بيئة العملة في ظروف استثنائية.',
    permissionsText: 'بِشَرطِ اتِّباعِ هَذِهِ الإِعْتِمَادِيَّةِ وَالقَانُونِ الْمُتَعَدِّدِ، بَدَاكِ تِسْتَعْمِلُ هَذِهِ الْخِدمَةَ كَمَا تُعْرَفُ لَكَ.',
    notAllowedItem1: 'استخدم الخدمة لتوزيع المحتوى غير القانوني حسب القوانين المعمول بها',
    notAllowedItem2: 'تغلب على، تعطيل، أو التدخل في ميزات الأمن المتعلقة بالخدمة',
    notAllowedItem3: 'لاَ تِستَخدِمِ الأَوسِيطِ الأَوتُومَاتِيَّةِ لِلدُّخُولِ إِلَى الخِدمَةِ إِلاَّ بِالطَرِيقَةِ المَسمُوحَةِ بِشَكْلٍ صَرِيحٍ',
    notAllowedItem5: 'استخدم الخدمة لتوزيع الرسائل غير المرغوب فيها أو الترويج الجماعي غير المرغوب فيه',
    notAllowedItem7: 'تخريب أو إبلاغ عن الاستخدام الخاطئ، أو عملية رفع العلم، أو عمليات الإدارة',
    monetizationItem1: 'الامتثال للقوانين في المناطق القانونية المعنية',
    monetizationOwnership: 'تبقى عندك كل حقوق الملكية على محتواك وتحق لك استغلالها من خلال آليات مختلفة كالتعويضات، الاشتراكات، بيع NFTs، ووسائل دخل مبنية على البلوكشين.',
    decentralizedModerationText: 'المُراقَبَة والتَحكيم للمحتوى على دِيهوب تُدار من خلال آليات الحُكم المُجتمعي:',
    decentralizedModerationItem1: 'المُلكين للتوكنات يُصوتون على سياسات المحتوى وأعمال التنفيذ',
