    decentralizedModerationItem4: 'السياسة بتتقرر من قبل إدارة النظام، مافيش فرد واحد بيقررها، و التنفيذ بتتكلف للمودرات المخصصين، وهم بيعملوا بسرعة.',
    designatedModeratorsText: 'المرشحين المختارين من المجتمع وذوي الأوسمة الرفيعة المستوى لديهم حقوق تقييد موكلة. يمكنهم إزالة المحتوى ووقف أو طرد الحسابات المزعجة بسرعة، دون انتظار تصويت حكومي، عندما يكون المحتوى غير قانوني أو ينتهك قواعد المجتمع أو يمثل خطرًا على المستخدمين.',
    designatedModeratorsItem2: 'مُعَيَّنِيْنَ المُتَوَقَّفِيْنَ يُسْتَعْضِلُوْنَ أو يُقَيِّدُوْنَ أو يُطْرَحُوْنَ مُبَارَحًا مُسْتَخْدِمِيْنَ مُسْتَعْبِرِيْنَ مُبَاشَرًا',
