    licenseToDeHubText: 'بِما تُقدِّمِ المُحتوى للخدمة، تُعطي دِيهاب (DeHub) إِذْنًا عالميًا غير مُحَدًّدًا، بلا حقوق مُتعلّقة، لاستِضافة وتوزيع مُحتواك عبر المنصة المُتوزّعة غَرضًا من تشغيل الخدمة.',
