    intro: 'دِهوب (DeHub) هيا منصة ديكنترياليزيت، ملكية المستخدمين، لكن ما هيا مكان بلا قواعيد. هده التوجيهات بتحدد ما هو مسموح بيه وما هو مش مسموح، كمان كيف تقدر تقارير محتوى، وما بيحصل بعد ما تقدر تقارير. القواعيد بتتعين من قبل حكم المجتمع، والتطبيق بيتم من قبل مديريين مخصصين بسرعة.',
